import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { writeFileSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const workspace = process.env.AF_WORKSPACE;
const dir = mkdtempSync(join(tmpdir(), 'af-invoice-consumer-'));
const file = join(dir, 'input.json');
const rows = [{id:'a',status:'paid',amountCents:1901},{id:'b',status:'draft',amountCents:70},{id:'c',status:'paid',amountCents:-101}];
writeFileSync(file, JSON.stringify(rows));
function run(args) { return spawnSync(process.execPath, [join(workspace,'cli.js'),file,...args], {cwd:workspace,encoding:'utf8',timeout:5000}); }
try {
  test('CLI consumer behavior', () => {
    for (const [args, expected] of [[[], rows], [['--summary'],{count:3,totalCents:1870}], [['--summary','--status','paid'],{count:2,totalCents:1800}], [['--status','paid','--summary'],{count:2,totalCents:1800}], [['--summary','--status','void'],{count:0,totalCents:0}]]) {
      const result = run(args); assert.equal(result.status,0,result.stderr); assert.deepEqual(JSON.parse(result.stdout),expected);
    }
    for (const args of [['--summary','--status'],['--summary','--status','--summary'],['--unknown'],['--summary','--status','']]) {
      const result = run(args); assert.notEqual(result.status,0); assert.ok(result.stderr.trim()); assert.doesNotMatch(result.stderr,/at file:|at ModuleJob/);
    }
    const missing = spawnSync(process.execPath,[join(workspace,'cli.js')],{encoding:'utf8',timeout:5000}); assert.notEqual(missing.status,0);
  });
} finally { process.on('exit', () => rmSync(dir,{recursive:true,force:true})); }

