import test from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
const root = process.env.AF_WORKSPACE;
const api = await import(pathToFileURL(join(root,'notes.js')));
const {createMemoryAdapter} = await import(pathToFileURL(join(root,'memory-adapter.js')));
test('consumer isolation and ownership', async () => {
  const service = api.createNotes();
  const note = {id:'shared',body:'A',meta:{labels:['private']}};
  await service.save('tenant-a',note); note.body='tampered'; note.meta.labels.push('tampered');
  await service.save('tenant-b',{id:'shared',body:'B'});
  assert.equal((await service.get('tenant-a','shared')).body,'A');
  assert.equal((await service.get('tenant-b','shared')).body,'B');
  assert.deepEqual((await service.get('tenant-a','shared')).meta.labels,['private']);
  const fetched = await service.get('tenant-a','shared'); fetched.meta.labels.push('changed');
  const listed = await service.list('tenant-a'); listed[0].body='changed'; listed[0].meta.labels.push('changed');
  assert.equal((await service.get('tenant-a','shared')).body,'A');
  assert.deepEqual((await service.get('tenant-a','shared')).meta.labels,['private']);
  assert.equal(await service.get('tenant-c','shared'),undefined);
  assert.deepEqual(await service.list('tenant-c'),[]);
  for (const [tenant,id,body] of [['a:b','c','first'],['a','b:c','second'],['__proto__','constructor','third']]) await service.save(tenant,{id,body});
  assert.equal((await service.get('a:b','c')).body,'first');
  assert.equal((await service.get('a','b:c')).body,'second');
  assert.equal((await service.get('__proto__','constructor')).body,'third');
  const adapter=createMemoryAdapter(); const shared=api.createNotes({adapter}); await shared.save('x',{id:'1',body:'shared'}); assert.equal((await api.createNotes({adapter}).get('x','1')).body,'shared');
});
test('injection, validation and error propagation', async () => {
  const calls=[]; const sentinel=new Error('storage unavailable');
  const adapter={async put(...args){calls.push(['put',...args]);},async get(...args){calls.push(['get',...args]);return undefined;},async list(...args){calls.push(['list',...args]);return [];}};
  const service=api.createNotes({adapter});
  await service.save('a',{id:'1',body:'ok'}); await service.get('a','1'); await service.list('a');
  assert.deepEqual(calls.map(c=>c[0]),['put','get','list']); assert.deepEqual(calls[0].slice(1),['a','1',{id:'1',body:'ok'}]);
  const count=calls.length;
  for (const operation of [()=>service.save('',{id:'1',body:'x'}),()=>service.save('a',{id:'',body:'x'}),()=>service.save('a',{id:'1',body:9}),()=>service.get(null,'1'),()=>service.get('a',''),()=>service.list('')]) await assert.rejects(async()=>operation());
  assert.equal(calls.length,count);
  const broken=api.createNotes({adapter:{async put(){throw sentinel;},async get(){throw sentinel;},async list(){throw sentinel;}}});
  for (const operation of [()=>broken.save('a',{id:'1',body:'x'}),()=>broken.get('a','1'),()=>broken.list('a')]) await assert.rejects(operation,error=>error===sentinel);
  assert.equal(api.save,undefined); assert.equal(api.get,undefined); assert.equal(api.list,undefined);
  const example=spawnSync(process.execPath,[join(root,'example.js')],{cwd:root,encoding:'utf8',timeout:5000}); assert.equal(example.status,0,example.stderr); assert.ok(Array.isArray(JSON.parse(example.stdout)));
});
